// js
const terms = get(ctx.subject.employment, 'terms', {});
const basis = get(terms, 'rate.unit', 'MONTHLY');
const work = get(terms, 'statutory_work_category', '');
const overtime_category = get(ctx.subject.employment, 'employee_extension_data.term_facts.overtime_category', '');
const normal = get(terms, 'normal_hours_per_day', null);
const day_hours =
	normal != null
		? Number(normal)
		: work === 'HAZARDOUS'
			? Number(ctx.lookup.hazardous_normal_hours_per_day)
			: Number(ctx.lookup.normal_hours_per_day);
const unit_wage =
	basis === 'PIECE' || basis === 'HOURLY'
		? Number(get(terms, 'rate.amount', 0))
		: basis === 'DAILY'
			? Number(get(terms, 'rate.amount', 0)) / day_hours
			: Number(ctx.base_pay) / (Number(ctx.lookup.monthly_divisor) * day_hours);
const multiple =
	overtime_category === 'SECTION_65_OTHER' ? 1 : Number(ctx.lookup.multiple);
const quantity = Number(get(ctx.run, 'source_manifest.overtime.OVERTIME', 0));
return unit_wage * multiple * quantity;

